package com.onrender.smartnf.health;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static com.onrender.smartnf.health.ShoppingListModels.*;import java.time.*;import java.util.*;import java.math.BigDecimal;import java.nio.file.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import java.util.function.Supplier;
public class ShoppingListTests {
 JdbcTemplate jdbc;ShoppingListService lists;TransactionTemplate tx;final LocalDate date=LocalDate.of(2026,11,30);
 @BeforeEach void setup() throws Exception {var ds=new org.springframework.jdbc.datasource.DriverManagerDataSource("jdbc:h2:mem:shopping-"+UUID.randomUUID()+";MODE=MySQL;DB_CLOSE_DELAY=-1","sa","");ds.setDriverClassName("org.h2.Driver");jdbc=new JdbcTemplate(ds);jdbc.execute("CREATE TABLE members(id BIGINT PRIMARY KEY)");jdbc.update("INSERT INTO members(id) VALUES(1),(2)");String schema;try(var in=getClass().getResourceAsStream("/db/migration/V27__create_shopping_lists.sql")){if(in!=null)schema=new String(in.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);else schema=Files.readString(Path.of("src/main/resources/db/migration/V27__create_shopping_lists.sql"));}for(String sql:schema.split(";"))if(!sql.isBlank())jdbc.execute(sql);lists=new ShoppingListService(jdbc);tx=new TransactionTemplate(new DataSourceTransactionManager(ds));}
 <T>T run(Supplier<T> action){return tx.execute(s->action.get());}
 Save request(UUID id,long revision,LocalDate day){return new Save(id,UUID.randomUUID(),revision,day,LocalDate.of(2026,12,1),LocalDate.of(2026,12,31),"MONTH",List.of(new Item("food","두부",new BigDecimal("123.125"))));}
 void code(int status,Runnable action){assertEquals(status,assertThrows(HealthException.class,action::run).status());}
 @Test void createRoundtripDateSeparateFromPeriodOwnershipAndCalendar(){var req=request(UUID.randomUUID(),0,date);var saved=run(()->lists.save(1,req));assertEquals(date,saved.shoppingDate());assertEquals(LocalDate.of(2026,12,1),saved.sourceFrom());assertEquals(new BigDecimal("123.125"),saved.items().getFirst().grams());assertEquals(saved,run(()->lists.get(1,saved.id())));assertEquals(1,lists.range(1,date,date).lists().size());assertTrue(lists.range(2,date,date).lists().isEmpty());code(404,()->lists.get(2,saved.id()));assertEquals(1,lists.counts(1,date,date).getFirst().count());assertTrue(lists.counts(2,date,date).isEmpty());}
 @Test void repeatedCreateAndUpdateConflictWithoutDuplicates(){UUID id=UUID.randomUUID();var req=request(id,0,date);var first=run(()->lists.save(1,req));assertEquals(first,run(()->lists.save(1,req)));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM shopping_lists",Integer.class));var changed=new Save(id,req.requestId(),0L,date.plusDays(1),req.sourceFrom(),req.sourceTo(),"MONTH",req.items());code(409,()->run(()->lists.save(1,changed)));var update=request(id,1,date.plusDays(2));var saved=run(()->lists.save(1,update));assertEquals(2,saved.revision());assertEquals(saved,run(()->lists.save(1,update)));assertTrue(lists.range(1,date,date).lists().isEmpty());code(409,()->run(()->lists.save(1,req)));code(409,()->run(()->lists.save(2,request(id,0,date))));}
 @Test void deleteIsRetryableErasesPayloadAndCannotResurrect(){UUID id=UUID.randomUUID();var req=request(id,0,date);run(()->lists.save(1,req));var del=new Delete(UUID.randomUUID(),1L);code(404,()->run(()->lists.delete(2,id,del)));var deleted=run(()->lists.delete(1,id,del));assertTrue(deleted.deleted());assertNull(deleted.shoppingDate());assertTrue(deleted.items().isEmpty());assertEquals(deleted,run(()->lists.delete(1,id,del)));code(404,()->lists.get(1,id));assertTrue(lists.counts(1,date,date).isEmpty());assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM shopping_list_items",Integer.class));code(409,()->run(()->lists.save(1,req)));}
 @Test void invalidDateAmountAndLongRangeRejected(){var good=request(UUID.randomUUID(),0,date);code(400,()->run(()->lists.save(1,new Save(good.id(),good.requestId(),0L,date,good.sourceFrom(),good.sourceTo(),"MONTH",List.of(new Item("","두부",BigDecimal.ZERO))))));code(400,()->run(()->lists.save(1,new Save(good.id(),good.requestId(),0L,date,good.sourceFrom(),good.sourceTo(),"MONTH",List.of(new Item("","두부",new BigDecimal("1.0001")))))));code(400,()->lists.range(1,date,date.plusDays(63)));code(400,()->run(()->lists.save(1,new Save(good.id(),good.requestId(),0L,LocalDate.of(2101,1,1),good.sourceFrom(),good.sourceTo(),"MONTH",good.items()))));}
 @Test void failureAfterDeletingChildrenRollsBackAndMemberDeleteCascades(){UUID id=UUID.randomUUID();var saved=run(()->lists.save(1,request(id,0,date)));jdbc.execute("ALTER TABLE shopping_list_items ADD CONSTRAINT fail_amount CHECK(grams < 200)");var change=new Save(id,UUID.randomUUID(),1L,date,saved.sourceFrom(),saved.sourceTo(),"MONTH",List.of(new Item("food","두부",new BigDecimal("999"))));assertThrows(org.springframework.dao.DataAccessException.class,()->run(()->lists.save(1,change)));assertEquals(saved,lists.get(1,id));jdbc.update("DELETE FROM members WHERE id=1");assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM shopping_lists",Integer.class));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM shopping_list_items",Integer.class));}
 @Test void sameDayMultipleListsAreCountedSeparately(){run(()->lists.save(1,request(UUID.randomUUID(),0,date)));run(()->lists.save(1,request(UUID.randomUUID(),0,date)));assertEquals(2,lists.counts(1,date,date).getFirst().count());assertEquals(2,lists.range(1,date,date).lists().size());}
 @Test void concurrentSameVersionHasOnlyOneWinner() throws Exception {UUID id=UUID.randomUUID();var start=new java.util.concurrent.CountDownLatch(1);try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var futures=new ArrayList<java.util.concurrent.Future<Integer>>();for(int i=0;i<2;i++){var request=request(id,0,date);futures.add(pool.submit(()->{start.await();try{run(()->lists.save(1,request));return 200;}catch(HealthException e){return e.status();}}));}start.countDown();var results=new ArrayList<Integer>();for(var f:futures)results.add(f.get(10,java.util.concurrent.TimeUnit.SECONDS));Collections.sort(results);assertEquals(List.of(200,409),results);assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM shopping_lists",Integer.class));}}

}
